pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    function testFuzz_property(bytes memory payload) public {
        SucceedsReceiver succ = new SucceedsReceiver();

        vm.deal(address(this), 1 ether);

        bool ok;
        try c.forward(address(succ), payload) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract SucceedsReceiver {
    fallback() external payable { }
    receive() external payable { }
}
